Model & Rule Management Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(model_rule_management_service, "Model & Rule Management Service") {
    Component(Rule_API_Router, "Rule API Router", "Python/FastAPI", "Exposes endpoints for fraud engineers and risk officers to manage and create rules and models.")
    Component(Rule_Management_Engine, "Rule Management Engine", "Python", "Validates, processes, and cryptographically signs rule bundles before distribution.")
    Component(Audit_Logger_Component, "Audit Logger Component", "Python", "Writes audit events to the external Audit Ledger to maintain tamper-evident compliance.")
}

Rel(Rule_API_Router, Rule_Management_Engine, "Routes rule and model payloads for processing")
Rel(Rule_Management_Engine, Audit_Logger_Component, "Triggers immutable audit logging for administrative actions")

@enduml

Amazon Aurora PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_aurora_postgresql, "Amazon Aurora PostgreSQL") {
    Component(aurora_postgresql_instance, "Aurora PostgreSQL Instance", "PostgreSQL 15+, Primary and Read Replica nodes", "System-of-record relational database deployed in AWS eu-west-1 for ACID compliance, multi-AZ high availability, and 7-year audit data storage.")
    Component(storage_volume, "Storage Volume", "Distributed, six-way replicated virtual volume", "Distributed storage across three Availability Zones ensuring data durability and high availability.")
